mapper.select:
SELECT group_id, project_id, last_processed_sequence, last_message_at, status, claim_token,
       attempt_count, next_attempt_at, correction, last_error, updated_at
FROM group_memory_state
WHERE (status = 'IDLE' OR updated_at < #{staleBefore})
AND group_id > #{afterGroupId}
ORDER BY group_id LIMIT #{limit}

mapper.update:
UPDATE group_memory_state
SET status = 'RUNNING', claim_token = #{now}, updated_at = #{now}
WHERE group_id = #{groupId} AND (status = 'IDLE' OR updated_at < #{staleBefore})

UPDATE group_memory_state
SET status = 'IDLE', claim_token = NULL,
    attempt_count = attempt_count + 1, next_attempt_at = #{nextAttemptAt},
    last_error = #{error}, updated_at = #{now}
WHERE group_id = #{groupId} AND status = 'RUNNING' AND claim_token = #{claimToken}

mapper.select:
SELECT g.* FROM group_memory_state g
JOIN chat_groups cg ON cg.id = g.group_id
WHERE cg.default_group = 1 AND g.discovery_attempt_count < #{maxAttempts}
  AND (g.discovery_next_attempt_at IS NULL OR g.discovery_next_attempt_at <= #{now})
ORDER BY g.group_id LIMIT #{limit}

mapper.update:
UPDATE group_memory_state
SET discovery_next_attempt_at = #{nextSlot}, updated_at = #{now}
WHERE group_id = #{groupId}
  AND (discovery_next_attempt_at IS NULL OR discovery_next_attempt_at <= #{now})

UPDATE group_memory_state
SET discovered_version = #{version}, discovery_attempt_count = 0,
    discovery_next_attempt_at = #{nextSlot}, discovery_error = NULL, updated_at = #{now}
WHERE group_id = #{groupId}

UPDATE group_memory_state
SET discovery_attempt_count = discovery_attempt_count + 1,
    discovery_next_attempt_at = #{nextAttemptAt}, discovery_error = #{error},
    updated_at = #{now}
WHERE group_id = #{groupId}
